import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    # Ensure we have exactly n numbers; ignore any extra if present.
    a = list(map(int, data[1:1 + n]))

    last_pos = {}
    best = n + 1  # larger than any possible subarray length

    for idx, val in enumerate(a):
        if val in last_pos:
            length = idx - last_pos[val] + 1
            if length < best:
                best = length
        last_pos[val] = idx

    if best == n + 1:
        print(-1)
    else:
        print(best)

