from collections import defaultdict

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Count how many windows of size k contain each value
        cnt = defaultdict(int)
        for start in range(n - k + 1):
            window_vals = set(nums[start:start + k])  # unique values in this window
            for v in window_vals:
                cnt[v] += 1

        # Find the largest value that appears in exactly one window
        answer = -1
        for v, c in cnt.items():
            if c == 1 and v > answer:
                answer = v
        return answer
