from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m = len(coins)
        n = len(coins[0])
        NEG_INF = -10**15          # sufficiently small sentinel

        # dp[i][j][k] = max coins reachable at (i,j) having used exactly k neutralizations
        dp = [[[NEG_INF] * 3 for _ in range(n)] for _ in range(m)]

        # start cell (0,0)
        dp[0][0][0] = coins[0][0]          # no neutralization used
        if coins[0][0] < 0:
            dp[0][0][1] = 0                # neutralize the start cell
        # dp[0][0][2] stays NEG_INF (cannot use two neutralizations on the same cell)

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = coins[i][j]
                for k in range(3):
                    # 1) Do NOT neutralize the current cell
                    best = NEG_INF
                    if i > 0:
                        best = max(best, dp[i-1][j][k])
                    if j > 0:
                        best = max(best, dp[i][j-1][k])
                    if best != NEG_INF:
                        dp[i][j][k] = max(dp[i][j][k], best + val)

                    # 2) Neutralize the current cell (only possible if it holds a robber)
                    if k > 0 and val < 0:
                        best2 = NEG_INF
                        if i > 0:
                            best2 = max(best2, dp[i-1][j][k-1])
                        if j > 0:
                            best2 = max(best2, dp[i][j-1][k-1])
                        if best2 != NEG_INF:
                            dp[i][j][k] = max(dp[i][j][k], best2)  # +0 after neutralization
        return max(dp[m-1][n-1])
