def is_samepatterns(p1, p2):
    """
    Returns True if the two sequences follow the same pattern of equality,
    i.e., for any indices i, j:
        p1[i] == p1[j]  <=>  p2[i] == p2[j]
    """
    if len(p1) != len(p2):
        return False

    # Convert each list to a canonical form where each new distinct element
    # gets the next integer id (0, 1, 2, ...) in order of first appearance.
    def canonical(seq):
        mapping = {}
        result = []
        for item in seq:
            if item not in mapping:
                mapping[item] = len(mapping)
            result.append(mapping[item])
        return result

    return canonical(p1) == canonical(p2)


