class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_len = 0
        n_s = len(s)
        n_t = len(t)

        # Enumerate all substrings of s (including the empty substring)
        for i in range(n_s + 1):
            for j in range(i, n_s + 1):
                sub_s = s[i:j]
                len_s = j - i

                # Enumerate all substrings of t (including the empty substring)
                for k in range(n_t + 1):
                    for l in range(k, n_t + 1):
                        sub_t = t[k:l]
                        total_len = len_s + (l - k)

                        # No need to check if it cannot improve the answer
                        if total_len <= max_len:
                            continue

                        combined = sub_s + sub_t
                        if combined == combined[::-1]:
                            max_len = total_len

        return max_len
