from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Prepare events for processing: sort by timestamp,
        # and ensure OFFLINE events are processed before MESSAGE events at the same timestamp.
        processed = []
        for ev in events:
            ts = int(ev[1])
            if ev[0] == "OFFLINE":
                order = 0   # OFFLINE first
            else:           # MESSAGE
                order = 1
            processed.append((ts, order, ev))
        processed.sort(key=lambda x: (x[0], x[1]))

        mentions = [0] * numberOfUsers
        # offline_until[u] = timestamp when user u becomes online again.
        # Initially all users are online => offline_until = 0.
        offline_until = [0] * numberOfUsers

        for _, _, ev in processed:
            if ev[0] == "OFFLINE":
                uid = int(ev[2])
                # user goes offline for 60 time units
                offline_until[uid] = int(ev[1]) + 60
            else:  # MESSAGE
                mention_str = ev[2]
                tokens = mention_str.split()
                for token in tokens:
                    if token == "ALL":
                        # mention every user regardless of online status
                        for uid in range(numberOfUsers):
                            mentions[uid] += 1
                    elif token == "HERE":
                        # mention only currently online users
                        for uid in range(numberOfUsers):
                            if offline_until[uid] <= int(ev[1]):
                                mentions[uid] += 1
                    else:
                        # token format: id<number>
                        uid = int(token[2:])  # strip the leading "id"
                        mentions[uid] += 1

        return mentions
